    /** كلمات تربط العبارة باحتياج؛ العبارة لا تظهر إلا لما يكون مؤشرها تحت الحد */
    static let tags: [String: [String]] = [
        "hunger": ["جوع", "أكل", "ناكل", "ياكل", "الغدا", "كبسة", "كيك", "عصير", "بسكوت", "يمي", "نفطر", "شوربة", "لذيذ", "الخضار", "تفاح", "موز", "حليب", "ساندويتش", "سندويتش", "عطشان", "تشرب", "أشرب", "مويه", "الثلاجة", "دجاج", "الفرن", "حلاو", "جزر"],
        "clean": ["وصخ", "ريحتك", "عرق", "نغسل", "اغسل", "أغسل", "أتروش", "فرّش", "فرش", "أسنان", "صابون", "فقاعات", "نظيف", "مويه", "شاور"],
        "health": ["تعبان", "تعور", "تعوّر", "يعوّر", "طحت", "دوا", "حرارة", "مريض", "كح", "لصقة"],
        "sleep": ["نعسان", "نوم", "نام", "ارتاح", "سرير!", "السرير"],
    ]

    static func needsOf(_ line: String) -> [String] { tags.filter { $0.value.contains { line.contains($0) } }.map { $0.key } }

    static func fits(_ store: Store, _ kid: String, _ line: String) -> Bool { needsOf(line).allSatisfy { store.need(kid, $0) < Needs.low } }

    static func doneLine(_ kid: Kid, _ kind: String) -> String? { done[group(kid)]?[kind]?.randomElement() }

    /** الحوار اللي يذكر احتياج ما يصير إلا لما يكون مؤشره تحت الحد عند واحد منهم */
    static func convoFits(_ store: Store, _ c: Convo) -> Bool {
        Set(c.lines.flatMap { needsOf($0) }).allSatisfy { m in min(store.need(c.a, m), store.need(c.b, m)) < Needs.low }
    }

    /** عبارة عشوائية تناسب الغرفة، بدون عبارات احتياج ما لها داعي */
    static func soloLine(_ store: Store, _ kid: Kid, _ room: String) -> String {
        Talk.solo(kid, room).filter { fits(store, kid.id, $0) }.randomElement()
            ?? (kid.toddler ? ["هييه! 🎉", "سلام! 👋", "يلا!"].randomElement()! : "😊")
    }

    static func forKid(_ store: Store, _ kid: Kid, _ room: String) -> [Act] {
        all.filter { a in
            a.room == room && a.lines[group(kid)] != nil &&
                (a.who == "all" || (a.who == "big" && !kid.toddler) || (a.who == "t" && kid.toddler)) &&
                (a.meter.map { store.need(kid.id, $0) < Needs.low } ?? true)
        }
    }
}
